#include "sfm_model_geometry.h"
#include "model_body_selection_candidate.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("model base path required");auto read=[](const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("asset missing");return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});};std::string base=argv[1];auto m=readSfmModelGeometryCandidate(read(base+".mdl"),read(base+".vvd"),read(base+".dx90.vtx"));std::cout<<"vertices="<<m.geometry.vertices.size()<<" skins="<<m.materials.skins.size()<<" body_groups="<<m.bodyModelCounts.size()<<'\n';for(size_t group=0;group<m.bodyModelCounts.size();++group)for(uint32_t part=0;part<m.bodyModelCounts[group];++part){size_t triangles=0;for(auto&mesh:m.meshes)if(mesh.body==group&&mesh.model==part)triangles+=mesh.triangles.size();std::cout<<"body_group="<<group<<" variant="<<part<<" base="<<m.bodyBases[group]<<" triangles="<<triangles<<'\n';}for(size_t skin=0;skin<m.materials.skins.size();++skin){size_t slots=0;for(auto&mesh:m.meshes){m.materials.resolve(skin,mesh.material);++slots;}std::cout<<"skin="<<skin<<" resolved_mesh_materials="<<slots<<'\n';}for(auto&mesh:m.meshes)if(mesh.materialType)std::cout<<"special_mesh body="<<mesh.body<<" model="<<mesh.model<<" mesh="<<mesh.mesh<<" material_slot="<<mesh.material<<" operation="<<mesh.materialType<<" parameter="<<mesh.materialParameter<<"\n";std::cout<<"eyeball_records="<<m.eyeballs.size()<<"\n";std::cout<<"alternate asset geometry inspection passed native_visual_parity=unverified\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
